import assert from 'node:assert/strict';
import path from 'node:path';
import {pathToFileURL} from 'node:url';
import {createInterface} from 'node:readline';
import {
  ROOT, bind, readJson, readBound, publish, same, keys, sha, formal, fileSha,
  assertBinding, decodeDigestTransportV001, type Json, type Binding,
} from './run_candidate_discovery_digest_skill_e2e_v001.mts';
import {runCandidateSelectionV001} from '../../runner/src/skills/candidate-selection-v001.js';
import {buildSelectionRequestV001, validateSelectionV001, promoteSelectionV001}
  from './candidate_selection_validation_v001.mts';
import {loadSelectionContextV001, SELECTION_IMPLEMENTATIONS}
  from './run_candidate_selection_e2e_v001.mts';

export const WORK = 'evals/clip_composition/outputs/presentation/work-candidate-selection-thin-plan-20260909-v001';
export const SOURCE_PLAN = 'evals/clip_composition/outputs/presentation/work-candidate-selection-20260908-v002/fixed-plan.json';
export const THIS_FILE = 'evals/clip_composition/run_thin_plan_candidate_selection_v0.mts';
export const IMPLEMENTATIONS = [...SELECTION_IMPLEMENTATIONS, THIS_FILE];
export const STRUCTURE_CONDITIONS = Object.freeze([
  '採用候補の元素材順を維持する。候補内部の編集はこの判断では指定しない。',
  '採用件数・目標尺・採用候補を事前に指定しない。',
]);
export type ThinPlanV0 = {schemaVersion: 'production-intent-plan-v0'; productionIntent: string};
export function assertThinPlanV0(v: unknown): asserts v is ThinPlanV0 {
  assert(keys(v, ['schemaVersion', 'productionIntent']) && v.schemaVersion === 'production-intent-plan-v0'
    && typeof v.productionIntent === 'string' && v.productionIntent.trim().length > 0, 'THIN_PLAN_INVALID');
}
const out = (c: Json, name: string) => `${c.plan.outputRoot}/${name}`;

/** 薄いplanを既存の制作要求欄へ投影する。採否・候補内容・判定基準は生成しない。 */
export function projectThinPlanV0(source: Json, thin: ThinPlanV0, bindings: {
  sourceContextBinding: Binding; thinPlanBinding: Binding; authorization: Binding;
  planId: string; outputRoot: string; implementationBindings: Json[];
}) {
  assertThinPlanV0(thin);
  assert(same(bindings.sourceContextBinding, source.planBinding), 'SOURCE_CONTEXT_BINDING_CHANGED');
  assert(same(bindings.thinPlanBinding, bind(bindings.thinPlanBinding.path, thin)), 'THIN_PLAN_BINDING_CHANGED');
  const plan = {...structuredClone(source.plan), ...structuredClone(bindings),
    schemaVersion: 'thin-plan-candidate-selection-evaluation-v0',
    request: {...structuredClone(source.plan.request), purpose: thin.productionIntent},
    structureConditions: [...STRUCTURE_CONDITIONS]};
  return plan;
}

function assertExperimentPlan(p: Json) {
  assert(keys(p, ['schemaVersion', 'planId', 'authorization', 'request', 'structureConditions', 'policy', 'skills',
    'reuseInternalRetention', 'acousticValidation', 'implementationBindings', 'outputRoot',
    'sourceContextBinding', 'thinPlanBinding']) && p.schemaVersion === 'thin-plan-candidate-selection-evaluation-v0', 'EXPERIMENT_PLAN_INVALID');
  assert(typeof p.planId === 'string' && /^[A-Za-z0-9][A-Za-z0-9._-]*$/u.test(p.planId), 'PLAN_ID_INVALID');
  assert(typeof p.outputRoot === 'string' && p.outputRoot.startsWith('evals/clip_composition/outputs/presentation/work-candidate-selection-thin-plan-')
    && /^[A-Za-z0-9._/-]+$/u.test(p.outputRoot) && !p.outputRoot.split('/').includes('..'), 'OUTPUT_ROOT_INVALID');
  for (const key of ['sourceContextBinding', 'thinPlanBinding', 'authorization']) assertBinding(p[key]);
  assert(Array.isArray(p.implementationBindings)
    && same(p.implementationBindings.map((b: Json) => b.path), IMPLEMENTATIONS), 'IMPLEMENTATION_MEMBERSHIP_INVALID');
}

/** 旧実験を再実行せず、その素材・候補・保持根拠を検査する既存の読取入口を利用する。 */
export async function loadThinPlanContextV0(planPath: string) {
  const plan = await readJson(planPath); assertExperimentPlan(plan);
  const [sourcePlan, thin, authorization] = await Promise.all([
    readBound(plan.sourceContextBinding), readBound(plan.thinPlanBinding), readBound(plan.authorization),
  ]);
  assertThinPlanV0(thin);
  assert(keys(authorization, ['schemaVersion', 'recordId', 'instruction', 'approvalQuote', 'scope'])
    && authorization.schemaVersion === 'thin-plan-selection-received-instruction-v0'
    && authorization.instruction === 'ZEV進行管理２ 指示-021（改訂版）'
    && authorization.approvalQuote === 'kawafmm承認済み。'
    && same(authorization.scope, {firstRunExistingSelectionUnchanged: true, fixedProductionIntent: true,
      sameExistingCandidates: true, noHistoricalHumanAnswersInJudgment: true, deterministicAdoption: true,
      existingOutputReuse: true, conditionalInternalRetention: true, conditionalRendering: true,
      humanQualitySeparate: true, paidApi: false, newMaterial: false}), 'AUTHORIZATION_INVALID');
  const source = await loadSelectionContextV001(plan.sourceContextBinding.path);
  assert(same(source.plan, sourcePlan), 'SOURCE_CONTEXT_CHANGED');
  for (const b of plan.implementationBindings) {
    assert(keys(b, ['path', 'fileSha256']) && await fileSha(path.join(ROOT, b.path)) === b.fileSha256, 'IMPLEMENTATION_CHANGED');
  }
  const expected = projectThinPlanV0(source, thin, {sourceContextBinding: plan.sourceContextBinding,
    thinPlanBinding: plan.thinPlanBinding, authorization: plan.authorization, planId: plan.planId,
    outputRoot: plan.outputRoot, implementationBindings: plan.implementationBindings});
  assert(same(plan, expected), 'THIN_PLAN_PROJECTION_CHANGED');
  return {...source, plan, planBinding: bind(planPath, plan), authorization, thinPlan: thin,
    sourceContextBinding: source.planBinding};
}

export async function prepareThinPlanEvaluationV0() {
  const source = await loadSelectionContextV001(SOURCE_PLAN);
  const thin: ThinPlanV0 = {schemaVersion: 'production-intent-plan-v0',
    productionIntent: 'ぺこらが本気で怖がって絶叫しているところと、怖がっている姿が可愛く見えるところを中心に見せる。'};
  const thinPlanBinding = await publish(`${WORK}/thin-plan-v0.json`, thin);
  const authorization = await publish(`${WORK}/received-instruction.json`, {
    schemaVersion: 'thin-plan-selection-received-instruction-v0', recordId: 'zev-instruction-021-revised-20260909',
    instruction: 'ZEV進行管理２ 指示-021（改訂版）', approvalQuote: 'kawafmm承認済み。',
    scope: {firstRunExistingSelectionUnchanged: true, fixedProductionIntent: true, sameExistingCandidates: true,
      noHistoricalHumanAnswersInJudgment: true, deterministicAdoption: true, existingOutputReuse: true,
      conditionalInternalRetention: true, conditionalRendering: true, humanQualitySeparate: true,
      paidApi: false, newMaterial: false},
  });
  const implementationBindings = await Promise.all(IMPLEMENTATIONS.map(async p => ({path: p, fileSha256: await fileSha(path.join(ROOT, p))})));
  const plan = projectThinPlanV0(source, thin, {sourceContextBinding: source.planBinding, thinPlanBinding,
    authorization, planId: 'candidate-selection-thin-plan-ymUsGrT6EaA-20260909-v001', outputRoot: WORK, implementationBindings});
  const planBinding = await publish(`${WORK}/fixed-plan.json`, plan);
  const current = await loadThinPlanContextV0(planBinding.path);
  const previousInput = buildSelectionRequestV001(source).input;
  const currentInput = buildSelectionRequestV001(current).input;
  assert(same(currentInput.candidates, previousInput.candidates), 'CANDIDATE_INPUT_CHANGED');
  assert(same(currentInput.criteria, previousInput.criteria), 'EXISTING_SELECTION_CRITERIA_CHANGED');
  assert.equal(currentInput.productionRequest, thin.productionIntent);
  await publish(`${WORK}/input-isolation-verification.json`, {
    schemaVersion: 'thin-plan-input-isolation-verification-v0', status: 'passed', planBinding, thinPlanBinding,
    candidateSetBinding: source.plan.request.candidateSet, candidateCount: currentInput.candidates.length,
    candidateInputUnchanged: true, existingSkillAndValidatorUnchanged: true, existingCriteriaUnchanged: true,
    changedInputFields: ['productionRequest', 'structureConditions'],
    changeMeaning: '制作要求を今回の具体的意図へ置換。旧ダイジェストという一般目標とその重複説明を外し、構造条件は元順と結果の事前指定禁止だけにした。過去の感想採否や構成上の正解を入力していない。',
    previousProductionRequest: previousInput.productionRequest, currentProductionRequest: currentInput.productionRequest,
    previousStructureConditions: previousInput.structureConditions, currentStructureConditions: currentInput.structureConditions,
    visibleInputKeys: Object.keys(currentInput), historicalHumanLabelsInJudgmentInput: false,
    previousSelectionAnswerReadForJudgment: false, priorOutputUseInformationInJudgmentInput: false,
    perceptualQualityFromTextNotEstablished: ['実際の声の絶叫の強さ', '本気で怖がっている印象', '怖がる姿の可愛さ'],
    humanQuality: 'not-evaluated',
  });
  return planBinding;
}

async function judgeThroughIsolatedStdin(request: Json) {
  // request全体や旧結果を提示せず、Skillが消費する本文と今回の制作要求だけを送る。
  process.stdout.write(JSON.stringify({event: 'thin-plan-selection-judgment-required',
    requestFileSha256: sha(formal(request)), input: request.input}) + '\n');
  const lines = createInterface({input: process.stdin, crlfDelay: Infinity, terminal: false});
  try {
    for await (const line of lines) return decodeDigestTransportV001(line);
    throw new Error('THIN_PLAN_JUDGMENT_INPUT_CLOSED');
  } finally {lines.close();}
}

export async function executeThinPlanSelectionV0(planPath: string) {
  const c = await loadThinPlanContextV0(planPath);
  const request = buildSelectionRequestV001(c);
  await publish(out(c, 'selection-request.json'), request);
  let response: Json | undefined;
  const result = await runCandidateSelectionV001(request.input, async input => {
    assert(same(input, request.input), 'EXISTING_SKILL_INPUT_CHANGED');
    response = await judgeThroughIsolatedStdin(request);
    await publish(out(c, 'selection-response.json'), response);
    return response.answer;
  });
  await publish(out(c, 'selection-result.json'), result);
  const fresh = await loadThinPlanContextV0(planPath);
  assert(same(fresh.planBinding, c.planBinding), 'PLAN_CHANGED_DURING_JUDGMENT');
  const promoted = promoteSelectionV001(validateSelectionV001(fresh, request, response!, result));
  await publish(out(c, 'selection-validation.json'), promoted.validation);
  await publish(out(c, 'candidate-adoption.json'), promoted.adoption);
  process.stdout.write(JSON.stringify({event: 'thin-plan-selection-completed',
    adopted: promoted.adoption.adoptedCandidates.map((p: Json) => p.candidateId),
    rejected: promoted.adoption.rejectedCandidates.map((p: Json) => p.candidateId), humanQuality: 'not-evaluated'}) + '\n');
  return promoted;
}

export async function verifyThinPlanSelectionV0(planPath: string) {
  const c = await loadThinPlanContextV0(planPath);
  const [request, response, result, validation, adoption] = await Promise.all([
    'selection-request.json', 'selection-response.json', 'selection-result.json', 'selection-validation.json', 'candidate-adoption.json',
  ].map(name => readJson(out(c, name))));
  const promoted = promoteSelectionV001(validateSelectionV001(c, request, response, result));
  assert(same(promoted.validation, validation) && same(promoted.adoption, adoption), 'THIN_PLAN_ADOPTION_CHANGED');
  return {c, request, response, result, ...promoted};
}
if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
  if (process.argv[2] === 'prepare') process.stdout.write(JSON.stringify(await prepareThinPlanEvaluationV0()) + '\n');
  else await executeThinPlanSelectionV0(process.argv[2]);
}

/** 今回の採否を再構築し、同じ編集区間の既存媒体を来歴付きで再利用する。新しいrenderの実績は作らない。 */
import assert from 'node:assert/strict';
import path from 'node:path';
import {access} from 'node:fs/promises';
import {pathToFileURL} from 'node:url';
import {ROOT, readJson, readBound, bind, publish, fileSha, same, type Json}
  from './run_candidate_discovery_digest_skill_e2e_v001.mts';
import {WORK, SOURCE_PLAN, verifyThinPlanSelectionV0} from './run_thin_plan_candidate_selection_v0.mts';
import {validateSelectionV001} from './candidate_selection_validation_v001.mts';
import {promoteSelectionForExecutionV001} from './run_candidate_selection_e2e_v001.mts';
import {verifyCandidateSelectionE2EV001} from './verify_candidate_selection_e2e_v001.mts';
import {projectAdoptedMediaRangesV001} from './adopted_media_manufacturing_v001.mts';
import {loadHistoricalCaptionRepairFixtureV001} from './replay_caption_local_repair_v001.mts';
import {captionRepairEffectiveInputsV001} from './caption_local_repair_common_v001.mts';
// @ts-expect-error Existing JavaScript media inspection; observed fields are checked below.
import {inspectRenderedMediaV002} from './presentation_renderer_qc_v002.mjs';

const EXISTING = path.posix.dirname(SOURCE_PLAN);
const FULL_REPAIR = 'evals/clip_composition/outputs/presentation/work-caption-local-repair-common-20260908-v001/ui-equivalence-v001/caption-repair-42ddb323-08da-44ef-bd2c-7780a95c13cc';
const THIS_FILE = 'evals/clip_composition/verify_thin_plan_output_reuse_v0.mts';

async function retainExact(p: string, value: Json) {
  try {await access(path.join(ROOT, p));}
  catch (error) {if ((error as NodeJS.ErrnoException).code === 'ENOENT') return publish(p, value); throw error;}
  assert(same(await readJson(p), value), 'SAVED_REUSE_EVIDENCE_CHANGED');
  return bind(p, value);
}

/** 意味判断後の媒体検査専用。過去字幕の人間観測は採否入力へ戻さない。 */
function normalizedCaptions(core: Json, retained: Set<number>) {
  const payload = captionRepairEffectiveInputsV001(core);
  const atoms = new Map<string, Json>(core.meaning.atomOccurrences.map((a: Json) => [a.atomOccurrenceId, a]));
  const sourceId = (id: string) => {const atom = atoms.get(id); assert(atom); return atom.sourceSegmentId;};
  return {styleProfileId: payload.styleProfileId, instructions: payload.instructions.flatMap((row: Json) => {
    const ids = row.targetProvenance.atomOccurrenceIds.map(sourceId);
    if (!ids.some((id: number) => retained.has(id))) return [];
    assert(ids.every((id: number) => retained.has(id)), 'PARTIAL_EXISTING_CAPTION_CANNOT_BE_REUSED');
    return [{semanticKind: row.semanticKind, content: row.content, sourceSegmentIds: ids,
      frames: row.outputTime, cueEndSourceSegmentId: sourceId(row.cueEndTextId),
      lineEndSourceSegmentIds: row.lineEndTextIds.map(sourceId), materialRefs: row.materialRefs}];
  })};
}

async function verifyExistingRepair(root: string) {
  const names = {meaning: 'meaning-input.json', sourcePackage: 'source-package.json', selection: 'selection.json',
    instruction: 'instruction.json', rendererJob: 'renderer-job.json', lineEndProjection: 'line-end-projection.json',
    cueEndProjection: 'cue-end-projection.json', captionAdoption: 'caption-adoption.json'};
  const core: Json = {}, artifacts: Json = {};
  for (const [key, filename] of Object.entries(names)) {
    core[key] = await readJson(`${root}/${filename}`); artifacts[key] = bind(`${root}/${filename}`, core[key]);
  }
  const execution = await readJson(`${root}/renderer-result.json`), job = core.rendererJob;
  assert(same(execution.rendererJobBinding, artifacts.rendererJob));
  assert.equal(execution.exitCode, 0); assert.equal(execution.result.status, 'completed');
  assert.equal(execution.result.qc.status, 'passed'); assert.deepEqual(execution.result.qc.violations, []);
  assert(same(await readBound(job.instructionArtifactBinding), core.instruction));
  assert(same(await readBound(job.lineEndProjectionBinding), core.lineEndProjection));
  const admission = await readJson(`${root}/admission-receipt.json`);
  assert(same(admission, execution.result.receipt)); assert.equal(admission.status, 'accepted');
  assert(same(admission.rendererJobBinding, artifacts.rendererJob));
  assert(same(admission.instructionArtifactBinding, artifacts.instruction));
  assert(same(admission.lineEndProjectionBinding, artifacts.lineEndProjection));
  assert(same(admission.instructionSourceBindings.meaningInformationPackage, artifacts.meaning));
  assert(same(admission.instructionSourceBindings.cueEndProjection, artifacts.cueEndProjection));
  assert(same(admission.cropAppliedBaseMediaBinding, job.cropAppliedBaseMedia));
  const layout = await readJson(`${root}/line-layout.json`); assert(same(layout, execution.result.lineLayout));
  const scope = await readJson(`${root}/scope-verification.json`);
  assert.equal(scope.status, 'passed'); assert(same(scope.effectiveInputs, captionRepairEffectiveInputsV001(core)));
  const base = job.cropAppliedBaseMedia;
  const timeline = await readBound(base.timeline), generation = await readBound(base.generationManifest);
  assert.equal(await fileSha(path.join(ROOT, base.baseMedia.path)), base.baseMedia.fileSha256);
  const videoPath = `${root}/render/presentation-rendered-v002.mp4`;
  const video = {path: videoPath, fileSha256: await fileSha(path.join(ROOT, videoPath))};
  const media = await inspectRenderedMediaV002(path.join(ROOT, videoPath));
  assert.equal(media.video.frameCount, timeline.baseMedia.expectedFrameCount); assert.equal(media.video.fps, 30);
  assert.equal(media.audio.packetPayloadSha256, generation.audio.encoded.packetPayloadSha256);
  return {core, timeline, generation, evidence: {artifacts, base, video, media,
    executionBinding: bind(`${root}/renderer-result.json`, execution), admissionBinding: bind(`${root}/admission-receipt.json`, admission),
    lineLayoutBinding: bind(`${root}/line-layout.json`, layout), scopeBinding: bind(`${root}/scope-verification.json`, scope),
    technicalQc: 'passed', humanQuality: 'not-evaluated'}};
}

export async function verifyThinPlanOutputReuseV0(planPath: string) {
  const selection = await verifyThinPlanSelectionV0(planPath), {c, request, response, result} = selection;
  const expected = promoteSelectionForExecutionV001(c, validateSelectionV001(c, request, response, result));
  // 新しい採否から編集範囲を確定してから、旧動画との一致を調べる。旧採否から新しい採否を作らない。
  const oldEdit = await readJson(`${EXISTING}/edit-plan.json`);
  assert(same(expected.editPlan.segments, oldEdit.segments), 'NEW_COMPOSITION_REQUIRES_DIFFERENT_MEDIA');
  assert(same(expected.editPlan.sourceVideoBinding, oldEdit.sourceVideoBinding), 'REUSE_SOURCE_CHANGED');
  const sourceProof = await verifyCandidateSelectionE2EV001(SOURCE_PLAN);
  assert.equal(sourceProof.status, 'passed');
  const final = await readJson(`${EXISTING}/final-verification.json`);
  const existing = await verifyExistingRepair(`${EXISTING}/caption-repair-v001`);
  assert(same(existing.evidence.video, final.renderer.video));
  assert(same(existing.evidence.base, final.base));
  for (const key of Object.keys(existing.evidence.artifacts)) assert(same(existing.evidence.artifacts[key], final.artifacts[key]));
  const inspection = await readJson(`${EXISTING}/source-media-inspection.json`);
  assert(same(inspection.sourceVideoBinding, c.plan.request.sourceVideo));
  const projected = projectAdoptedMediaRangesV001(expected.editPlan, inspection.media);
  assert(same(projected.mappings, existing.generation.segments), 'NEW_FORMAL_RANGE_PROJECTION_DIFFERS');
  assert(same(projected.mappings.map(({audioSamples, ...s}: Json) => s), existing.timeline.segments));
  const historical = await loadHistoricalCaptionRepairFixtureV001('digest');
  const retained = new Set<number>(expected.adoption.segments.flatMap((s: Json) => s.sourceSegmentIds));
  const oldMeaning = await readBound(historical.source.artifacts.meaning);
  const oldTimeline = await readBound(historical.source.base.timeline);
  // この結果で一致した元フレーム・音声対応を条件とし、字幕の出力位置を恣意的に移動しない。
  assert(same(existing.timeline.segments, oldTimeline.segments.slice(0, existing.timeline.segments.length)));
  const payload = normalizedCaptions(existing.core, retained);
  assert(same(payload, normalizedCaptions({...historical.expected, meaning: oldMeaning}, retained)));
  const full = await verifyExistingRepair(FULL_REPAIR);
  assert.equal(full.evidence.video.fileSha256, historical.fixture.expectedVideo.fileSha256, 'COMPARISON_VIDEO_BYTES_CHANGED');
  assert(same(full.timeline, oldTimeline));
  assert(same(captionRepairEffectiveInputsV001(full.core), captionRepairEffectiveInputsV001(historical.expected)));
  assert(same(normalizedCaptions(full.core, retained), payload));
  const previousResponse = await readJson(`${EXISTING}/selection-response.json`);
  const decisionComparison = result.answer.decisions.map((d: Json, i: number) => ({candidateId: d.candidateId,
    before: previousResponse.answer.decisions[i].decision, after: d.decision,
    beforeBasis: previousResponse.answer.decisions[i].basis, afterBasis: d.basis,
    reasonChanged: previousResponse.answer.decisions[i].reason !== d.reason}));
  const adoptionBinding = await retainExact(`${WORK}/machine-adoption.json`, expected.adoption);
  const editPlanBinding = await retainExact(`${WORK}/edit-plan.json`, expected.editPlan);
  const sourceProofBinding = await retainExact(`${WORK}/reused-source-core-verification.json`, sourceProof);
  const formalReuseInput = {schemaVersion: 'thin-plan-existing-media-reuse-input-v0', planBinding: c.planBinding,
    authorizationBinding: c.plan.authorization, machineAdoptionBinding: adoptionBinding, editPlanBinding,
    currentSelectionValidation: bind(`${WORK}/selection-validation.json`, expected.validation),
    sourceCoreProofBinding: sourceProofBinding, sourceFinalVerificationBinding: bind(`${EXISTING}/final-verification.json`, final),
    resolvedMediaMappings: projected.mappings, unchangedCaptionPayload: payload,
    selectedOutput: existing.evidence, comparisonOutput: full.evidence,
    mode: 'reuse-existing-bytes-after-current-composition-and-payload-equivalence',
    newRendererExecution: false, inheritedHumanQuality: false};
  const reuseBinding = await retainExact(`${WORK}/formal-output-reuse-input.json`, formalReuseInput);
  const proof = {schemaVersion: 'thin-plan-output-reuse-verification-v0', status: 'passed', planBinding: c.planBinding,
    formalReuseInputBinding: reuseBinding, implementationBinding: {path: THIS_FILE, fileSha256: await fileSha(path.join(ROOT, THIS_FILE))},
    decisions: decisionComparison, counts: {candidates: c.candidateSet.candidates.length,
      adopted: expected.adoption.adoptedCandidates.length, rejected: expected.adoption.rejectedCandidates.length},
    selectedOutput: existing.evidence.video, comparisonOutput: full.evidence.video,
    selectedFrames: existing.timeline.baseMedia.expectedFrameCount, comparisonFrames: full.timeline.baseMedia.expectedFrameCount,
    captions: payload.instructions.length, checks: {newJudgmentReconstructed: true, deterministicAdoption: true,
      existingRetentionReconstructed: true, currentFormalRangesMatchExistingMedia: true, sourceCoreReconstructed: true,
      existingCommonRepairPayloadExact: true, existingRendererAdmissionAndQcBound: true, renderedByteHashes: true,
      observedFramesAndAudioPackets: true, previousHumanAnswersExcludedFromNewJudgment: true},
    newInternalRetentionJudgment: false, newRenderCount: 0, partialCandidateUseRequired: false,
    humanQuality: 'not-evaluated', inputImprovementEstablished: false, existingSkillChangeRequired: false};
  await retainExact(`${WORK}/output-reuse-verification-v002.json`, proof);
  return proof;
}
if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
  const proof = await verifyThinPlanOutputReuseV0(process.argv[2]);
  process.stdout.write(JSON.stringify(proof) + '\n');
}

import assert from 'node:assert/strict';
import test from 'node:test';
import {assertThinPlanV0, projectThinPlanV0, STRUCTURE_CONDITIONS} from './run_thin_plan_candidate_selection_v0.mts';
import {bind} from './run_candidate_discovery_digest_skill_e2e_v001.mts';

const thin = {schemaVersion: 'production-intent-plan-v0' as const, productionIntent: '困難に向き合う反応を見せる。'};
function fixture() {
  const plan = {schemaVersion: 'test-plan-v0', request: {purpose: '以前の目的', sourceId: 'source-x', candidateSet: {path: 'candidates.json'}},
    structureConditions: ['以前の条件'], policy: {adoptionCountTarget: null}, skills: [{id: 'candidate-selection'}]};
  const source = {plan, planBinding: bind('source-plan.json', plan)};
  return {source, bindings: {sourceContextBinding: source.planBinding, thinPlanBinding: bind('thin.json', thin),
    authorization: bind('authorization.json', {schemaVersion: 'test-authorization-v0', instruction: 'new'}), planId: 'new-plan', outputRoot: 'new-output',
    implementationBindings: []}};
}
test('thin plan rejects adopted IDs, duration targets, roles and human answers', () => {
  for (const field of ['adoptedCandidates', 'targetDuration', 'roles', 'historicalHumanAnswer', 'cutTimes']) {
    assert.throws(() => assertThinPlanV0({...thin, [field]: 'injected'}), /THIN_PLAN_INVALID/);
  }
  assert.throws(() => assertThinPlanV0({...thin, productionIntent: ' '}), /THIN_PLAN_INVALID/);
});
test('intent projection retains candidate references and rules without mutating the source', () => {
  const {source, bindings} = fixture();
  const before = structuredClone(source);
  const result = projectThinPlanV0(source, thin, bindings);
  assert.deepEqual(source, before);
  assert.equal(result.request.purpose, thin.productionIntent);
  assert.deepEqual(result.request.candidateSet, source.plan.request.candidateSet);
  assert.deepEqual(result.policy, source.plan.policy);
  assert.deepEqual(result.skills, source.plan.skills);
  assert.deepEqual(result.structureConditions, STRUCTURE_CONDITIONS);
  result.request.candidateSet.path = 'mutation';
  assert.deepEqual(source, before);
});
test('a changed purpose cannot keep a previous thin-plan binding', () => {
  const {source, bindings} = fixture();
  assert.throws(() => projectThinPlanV0(source, {...thin, productionIntent: '別の目的'}, bindings), /THIN_PLAN_BINDING_CHANGED/);
});
test('a substituted source context cannot inherit the recorded source binding', () => {
  const {source, bindings} = fixture();
  assert.throws(() => projectThinPlanV0(source, thin, {...bindings,
    sourceContextBinding: bind('other.json', source.plan)}), /SOURCE_CONTEXT_BINDING_CHANGED/);
});

import assert from 'node:assert/strict';
import test from 'node:test';
import {verifyThinPlanSelectionV0, WORK} from './run_thin_plan_candidate_selection_v0.mts';
import {buildSelectionRequestV001, validateSelectionV001} from './candidate_selection_validation_v001.mts';
import {promoteSelectionForExecutionV001} from './run_candidate_selection_e2e_v001.mts';
import {readJson, same, type Json} from './run_candidate_discovery_digest_skill_e2e_v001.mts';
const actual = await verifyThinPlanSelectionV0(`${WORK}/fixed-plan.json`);
const {c, request, response, result} = actual;

test('the frozen purpose reaches the Skill while candidate text and original rules stay identical', async () => {
  const previous = await readJson(`${c.sourceContextBinding.path.replace(/fixed-plan.json$/u, '')}selection-request.json`);
  assert.equal(request.input.productionRequest, c.thinPlan.productionIntent);
  assert(same(request.input.candidates, previous.input.candidates));
  assert(same(request.input.criteria, previous.input.criteria));
  assert.deepEqual(Object.keys(c.thinPlan), ['schemaVersion', 'productionIntent']);
});
test('historical adoption fields in the execution context cannot enter the closed judgment input', () => {
  const poisoned: Json = structuredClone(c);
  poisoned.retention.humanQuality = 'historical-answer';
  poisoned.retention.recommendKeepCandidate = 'candidate-0003';
  poisoned.oldSelectionResponse = {answer: 'keep everything'};
  assert(same(buildSelectionRequestV001(poisoned), request));
});
test('an old-plan response cannot substitute for the fresh bound judgment', async () => {
  const old = await readJson(`${c.sourceContextBinding.path.replace(/fixed-plan.json$/u, '')}selection-response.json`);
  assert.throws(() => validateSelectionV001(c, request, old, result), /JUDGMENT_PROVENANCE_INVALID/);
});
test('mutated current reasons and unvalidated internal cuts have no execution authority', () => {
  const changed: Json = structuredClone(result);
  changed.answer.decisions[0].reason = '後から人間回答に合わせた理由';
  assert.throws(() => validateSelectionV001(c, request, response, changed), /JUDGMENT_PROVENANCE_INVALID/);
  const altered: Json = structuredClone(c); altered.retention.segments[0].sourceEndMs++;
  assert.throws(() => promoteSelectionForExecutionV001(altered, validateSelectionV001(c, request, response, result)), /RETENTION_RECONSTRUCTION_INVALID/);
});
test('newly bound adoption and formal editing input reconstruct and keep only selected candidates', async () => {
  const rebuilt = promoteSelectionForExecutionV001(c, validateSelectionV001(c, request, response, result));
  assert(same(rebuilt.adoption, await readJson(`${WORK}/machine-adoption.json`)));
  assert(same(rebuilt.editPlan, await readJson(`${WORK}/edit-plan.json`)));
  const selected = new Set(actual.adoption.adoptedCandidates.map((r: Json) => r.candidateId));
  assert(rebuilt.editPlan.segments.every((s: Json) => selected.has(s.candidateId)));
  assert.equal(rebuilt.adoption.historicalHumanQualityInherited, false);
});

